#[inline]
pub fn word_entry(index: usize) -> (u8, u8, u16) {
    // (length | 0x80 terminator flag, transform, word index)
    let w = STATIC_DICTIONARY_WORDS[index];
    let l = (w & 0x3F) as u8;
    let t = ((w >> 6) & 0x7F) as u8;
    let i = (w >> 13) as u16;
    (l, t, i)
}
